import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第23章 水龙头","description":"","frontmatter":{},"headers":[],"relativePath":"第23章_水龙头.md","filePath":"第23章_水龙头.md"}'),r={name:"第23章_水龙头.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第23章-水龙头" tabindex="-1">第23章 水龙头 <a class="header-anchor" href="#第23章-水龙头" aria-label="Permalink to &quot;第23章 水龙头&quot;">​</a></h1><p>开学之后我才发现一件事：离得近了，反而更难见面。</p><p>我们不在一个班。她在二楼，我在三楼。上课时间一样，下课时间一样，可两个班的走廊方向相反。课间十分钟，走路过去来回就要五分钟，中间还要穿过一段有值日老师站岗的连廊。</p><p>我们也不能公开说话。她第一天就交代过：学校里的事，谁都不知道。</p><p>我说好。</p><p>她说，你别觉得我小题大做。</p><p>我说，我没觉得。</p><p>她说，你不懂。</p><p>我确实不懂。我在南雾的时候只知道她家管得紧，到了这边才知道，这边的学校比南雾管得更细。手机要交，出入要登记，晚上查寝。她那边的班主任管得尤其严，据说上学期有两个人因为被拍到走在一起，叫了家长。</p><p>所以她谨慎是对的。</p><p>那阵子我的日子被排得很满。</p><p>早上六点起，跑操，早读，上午四节课，中午在教室趴一会儿，下午三节课，晚上自习到十点。我把所有时间都填上了。</p><p>填满时间我以为很有效。后来发现不是。因为她在同一所学校里。</p><p>我知道她在二楼，知道她大概几点去食堂，知道她哪节课是体育。这些都不用她告诉我，我自己就记住了。</p><p>沈聿有一次问我，你是不是认识二楼的一个女生。</p><p>我说，没有。</p><p>他说，那天我看见你看二楼那个方向。</p><p>我说，我在看那边有棵树。</p><p>他说，你看树看那么久。</p><p>我说，树长得好看。</p><p>他看了我一眼，没再说。</p><p>开学第一周我们只在走廊上遇见过两次。</p><p>第一次是她上楼交作业，我在三楼楼梯口，她低着头快步走过来，从我身边过去了。擦肩的时候她没看我，我也没敢看她。</p><p>走出去几步，我手机震了一下。</p><p>她说：刚才那个是你。</p><p>我说：是。</p><p>她说：你头发怎么那么乱。</p><p>我说：刚跑完操。</p><p>她说：哦。</p><p>第二次是在食堂。我端着盘子找位置，看见她坐在靠窗那边。她也看见了我。我们对视了一下，然后各自低头。</p><p>那天晚上她发消息说，食堂人太多。</p><p>我说，我知道。</p><p>第二周的一天下午，我们上体育课。</p><p>体育课在操场，正好她们班也在。女生在操场东边做形体，男生在西边跑八百米。我跑到一半就看见了，她站在队伍里，穿着校服，正在听老师说话。</p><p>我跑完去了水龙头那边洗脸。</p><p>那排水龙头在水房外面，一共六个，早坏了三个。剩下的三个水很小，水柱细细的。我拧开一个，把脸凑过去。</p><p>水很凉。凉得我一下子清醒了。</p><p>我正低着头冲，旁边有人站到了我边上。</p><p>我以为是同学，没抬头。</p><p>那个人说话了。</p><p>她说，这个水不能喝。</p><p>我抬起头。</p><p>是她。</p><p>她手里拿着一瓶水。校服袖口往上挽了一点，露出细瘦的手腕。她站得离我一步远，眼睛看着那排水龙头，不看我。</p><p>我说，你怎么过来了。</p><p>她说，我路过。</p><p>我说，你们班在东边。</p><p>她说，我绕的。</p><p>我接过那瓶水。瓶身上还有凉气，是她刚从冰柜里拿的。</p><p>我说，那你怎么办。</p><p>她说，我还有一瓶。</p><p>我把瓶盖拧开，喝了一口。</p><p>她一直看着那排水龙头。</p><p>她说，我初一的时候喝过一次，第二天肚子疼。</p><p>我说，那你现在告诉我是为什么。</p><p>她说，怕你也疼。</p><p>我说，那你直接说不就行了。</p><p>她说，我懒。</p><p>她把话说完，往后退了一步。</p><p>她说，我回去了。</p><p>我说，好。</p><p>她说，你别站在这里。</p><p>我说，为什么。</p><p>她说，女生那边看得到。</p><p>她走了。走的时候还是低着头，快步，从操场边缘绕过去。她走了大概二十步，我才发现她手里其实只拿了一瓶水。</p><p>那一瓶给我了。她说她还有一瓶，是骗我的。</p><p>那天晚上我问她。</p><p>我说，你是不是把水给我了。</p><p>她说，没有。</p><p>我说，那你手里呢。</p><p>她说，我喝了。</p><p>我说，你上午说的还有一瓶。</p><p>她说，我记错了。</p><p>我不问了。</p><p>我把那个空瓶留下来了。喝完冲干净，放在宿舍的柜子里。柜子小，就放了一排书和一个空瓶子，瓶子被书挡着。</p><p>后来那个瓶子我一直没扔。</p><p>有一次宿舍大扫除，值周的同学翻出来，问是不是垃圾。</p><p>我说，不是。</p><p>他说，一个空瓶子你留着干嘛。</p><p>我说，装水。</p><p>他说，你装水不会用杯子？</p><p>我说，习惯了。</p><p>他没再问，把瓶子放回去。</p><p>我在心里想过很多遍那天的事。她绕过半个操场，从东边绕到西边，只为了跟我说一句水不能喝。她完全可以晚上在手机上跟我说。她不用走那一段路，不用冒被同学看到的险。</p><p>可她走了。</p><p>后来我也做过同样的事。</p><p>有一天早上我在食堂多买了一个包子，用纸包着，放在书包里。中饭前我绕到二楼那边走了一趟，把包子放在她教室门口的窗台上。</p><p>那天晚上她发消息说：你放的？</p><p>我说：嗯。</p><p>她说：凉了。</p><p>我说：下次早点放。</p><p>她说：没有下次。</p><p>我问：为什么。</p><p>她说：那个窗台有人看着。</p><p>我说：什么人。</p><p>她说：她们班的人。</p><p>我那时候还不明白这是为什么。后来我明白了：有些话，是必须当面说的。写在屏幕上的那句话，跟站在那里说出来，不是同一句。</p><p>她大概也知道。</p><p>所以那天她绕了半个操场。</p><p>而我能做的，只是把那个空瓶子留着。</p><p>那年冬天宿舍换了一次柜子，旧的搬下楼。搬柜子的时候我把那个瓶子拿出来，用纸巾包好，放进了书包。</p><p>寒假回家，奶奶看见我从包里掏出一个空瓶子，问这是什么。</p><p>我说，装水的。</p><p>她说，家里没有瓶子吗。</p><p>我说，这个好用。</p><p>她看了看那个瓶子，瓶身上的标签都磨掉了，只剩一块白。她没再问。</p><p>那个瓶子后来一直在我书桌上。我给它装了半瓶水，放在那里，一直没喝。</p><p>水一周就浑了。我把它倒了，重新装。</p><p>后来我养成了一个习惯：隔几天就换一次水，一直没有让它空着。这个习惯我保持了很久很久。</p>',109)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
